, "open_access": {"is_oa": true, "oa_status": "gold", "oa_url": "https://www.techrxiv.org/doi/pdf/10.36227/techrxiv.177126510.00438262", "any_repository_has_fulltext": null}, "primary_location": {"id": "doi:10.36227/techrxiv.177126510.00438262/v1", "doi": "https://doi.org/10.36227/techrxiv.177126510.00438262/v1", "is_oa": true, "landing_page_url": "https://doi.org/10.36227/techrxiv.177126510.00438262/v1", "pdf_url": "https://www.techrxiv.org/doi/pdf/10.36227/techrxiv.177126510.00438262", "source": null, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "acceptedVersion", "is_accepted": true, "is_published": false, "raw_source_name": null, "raw_type": "posted-content"}, "abstract": "Large language models produce fluent text but struggle with systematic reasoning, often hallucinating confident but unfounded claims. When Apple researchers added irrelevant context to mathematical problems, LLM performance degraded by 65% Apple Machine Learning Research [2024a], exposing brittle pattern-matching beneath apparent reasoning. This epistemic gap-the inability to ground claims in traceable evidence-limits AI reliability in domains requiring justification. We introduce Pramana, a novel approach that teaches LLMs explicit epistemological methodology by fine-tuning on Navya-Nyaya logic, a 2,500-year-old Indian reasoning framework. Unlike generic chain-of-thought prompting, Navya-Nyaya enforces structured 6-phase reasoning: SAMSHAYA (doubt analysis), PRAMANA (evidence source identification), PANCHA AVAYAVA (5-member syllogism with universal rules), TARKA (counterfactual verification), HETVABHASA (fallacy detection), and NIRNAYA (ascertainment distinguishing knowledge from hypothesis). This integration of logic and epistemology provides cognitive scaffolding absent from standard reasoning approaches. We fine-tune Llama 3.2-3B and DeepSeek-R1-Distill-Llama-8B on 55 Nyaya-structured logical problems (constraint satisfaction, Boolean SAT, multi-step deduction). Stage 1 achieves 100% semantic correctness on held-out evaluation despite only 40% strict format adherence-revealing that models internalize reasoning content even when structural enforcement is imperfect. Ablation studies show format prompting and temperature critically affect performance, with optimal configurations differing by stage. We release all models, datasets, and training infrastructure on Hugging Face to enable further research on epistemic frameworks for AI reasoning."}]", "excerpt_truncated": true, "source_sha256": "a1bb05813670d88ad223daec868cdea4a8437247943969cc351385732ab0d78a", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2307.05782", "doi:10.48550/arxiv.2508.15361", "doi:10.36227/techrxiv.177126510.00438262", "doi:10.36227/techrxiv.177126510.00438262/v1", "openalex:W4384389564", "openalex:W4416050957", "arxiv:2307.05782", "arxiv:2508.15361"], "source_candidates": ["https://doi.org/10.48550/arxiv.2307.05782", "https://arxiv.org/pdf/2307.05782", "https://doi.org/10.48550/arxiv.2508.15361", "https://arxiv.org/pdf/2508.15361", "https://doi.org/10.36227/techrxiv.177126510.00438262/v1"], "source_candidate_identities": {}}

